package cli

import (
	_ "embed"
	"fmt"
	"os"
	"sort"
	"strings"
)

//go:embed sample_config.yml
var sampleConfig []byte

// Use a registered embed relative to this package directory.

const version = "v0.23.4"

const banner = `
      ____         _ __       _
     |  _ \   ___ |  _ \    _| |_  _ __  ___   ___
     | | | | / _ \| |_) |  |_   _||  __|/ _ \ / _ \
     | |_| ||  __/| .__/     | |  | |  |  __/|  __/
     |____/  \__| |_|        | \__|_|   \___| \___|
`

// Flag represents a single flag.
type Flag struct {
	Name      string
	Short     string
	Kind      string // "bool", "string", "stringArray"
	Help      string
	Default   string // default repr (for string); "false"/"true" for bool
	Persistent bool
}

// flagRepr returns the left-hand column text for a flag.
func (f *Flag) repr() string {
	var sb strings.Builder
	sb.WriteString("  ")
	if f.Short != "" {
		sb.WriteString("-" + f.Short + ", ")
	} else {
		sb.WriteString("    ")
	}
	sb.WriteString("--" + f.Name)
	switch f.Kind {
	case "string":
		sb.WriteString(" string")
	case "stringArray":
		sb.WriteString(" stringArray")
	}
	return sb.String()
}

func (f *Flag) description() string {
	d := f.Help
	switch f.Kind {
	case "bool":
		d += fmt.Sprintf(" (default %s)", f.Default)
	case "string":
		if f.Default != "" {
			d += fmt.Sprintf(" (default %s)", f.Default)
		}
	}
	return d
}

// Command represents a subcommand.
type Command struct {
	Name         string
	Aliases      []string
	ShortDesc    string
	LongDesc     string
	ArgsMin      int  // -1 for no min
	ArgsMax      int  // -1 for no max
	ArgsExact    int  // -1 for no exact
	Flags        []*Flag
	Run          func(root *Root, cmdline *Parsed) int
	ExtraFlags   []*Flag // appended to Flags in flag listing
	HasJsonFlag  bool
}

// Root command definition.
type Root struct {
	Commands []*Command
	// parsed global flag values
	Config                         string
	ConfigSet                      bool
	UnwrapExports                  bool
	JsTsConfigPaths                bool
	JsWorkspaces                   bool
	PythonExcludeConditionalImports bool
	Only                           []string
	Exclude                        []string
}

// The global/persistent flags (in registration order).
func (r *Root) persistentFlags() []*Flag {
	return []*Flag{
		{Name: "config", Short: "c", Kind: "string", Default: ".dep-tree.yml",
			Help: "path to dep-tree's config file.", Persistent: true},
		{Name: "unwrap-exports", Kind: "bool", Default: "false",
			Help: "trace re-exported symbols to the file where they are declared.", Persistent: true},
		{Name: "js-tsconfig-paths", Kind: "bool", Default: "true",
			Help: "follow the tsconfig.json paths while resolving imports.", Persistent: true},
		{Name: "js-workspaces", Kind: "bool", Default: "true",
			Help: "take the workspaces attribute in the root package.json into account for resolving paths.", Persistent: true},
		{Name: "python-exclude-conditional-imports", Kind: "bool", Default: "false",
			Help: "exclude imports wrapped inside if or try statements.", Persistent: true},
		{Name: "only", Kind: "stringArray", Default: "",
			Help: "Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.", Persistent: true},
		{Name: "exclude", Kind: "stringArray", Default: "",
			Help: "Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.", Persistent: true},
	}
}

// Root local (non-persistent) flags that only belong to the root.
func rootLocalFlags() []*Flag {
	return []*Flag{
		{Name: "help", Short: "h", Kind: "bool", Default: "false",
			Help: "help for dep-tree"},
		{Name: "version", Short: "v", Kind: "bool", Default: "false",
			Help: "version for dep-tree"},
	}
}

// formatFlags formats a list of flags with aligned columns.
func formatFlags(flags []*Flag) string {
	maxLen := 0
	reprs := make([]string, len(flags))
	for i, f := range flags {
		reprs[i] = f.repr()
		if len(reprs[i]) > maxLen {
			maxLen = len(reprs[i])
		}
	}
	var sb strings.Builder
	for i, f := range flags {
		sb.WriteString(reprs[i])
		sb.WriteString(strings.Repeat(" ", maxLen-len(reprs[i])+3))
		sb.WriteString(f.description())
		sb.WriteString("\n")
	}
	return sb.String()
}

// sortFlagsByName sorts flags alphabetically by long name.
func sortFlagsByName(flags []*Flag) []*Flag {
	out := make([]*Flag, len(flags))
	copy(out, flags)
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].Name < out[j].Name
	})
	return out
}

// renderRootHelp renders the root help to the writer.
func renderRootHelp(w *strings.Builder) {
	w.WriteString(banner)
	w.WriteString("\n")
	w.WriteString("Usage:\n")
	w.WriteString("  dep-tree [command]\n")
	w.WriteString("\n")
	w.WriteString("Examples:\n")
	w.WriteString("$ dep-tree src/index.ts\n")
	w.WriteString("$ dep-tree entropy src/index.ts\n")
	w.WriteString("$ dep-tree tree package/main.py --unwrap-exports\n")
	w.WriteString("$ dep-tree check\n")
	w.WriteString("\n")

	// Groups of commands
	w.WriteString("Visualize your dependencies graphically\n")
	w.WriteString("  entropy     (default) Renders a 3d force-directed graph in the browser\n")
	w.WriteString("  tree        Render the dependency tree starting from the provided entrypoint\n")
	w.WriteString("\n")
	w.WriteString("Check your dependencies against your own rules\n")
	w.WriteString("  check       Checks that the dependency rules defined in the configuration file are not broken\n")
	w.WriteString("\n")
	w.WriteString("Display what are the dependencies between two portions of code\n")
	w.WriteString("  explain     Shows all the dependencies between two parts of the code\n")
	w.WriteString("\n")
	w.WriteString("Additional Commands:\n")
	w.WriteString("  config      Generates a sample config in case that there's not already one present\n")
	w.WriteString("  help        Help about any command\n")
	w.WriteString("\n")

	// Flags block: persistent flags in registration order, then local flags
	r := &Root{}
	allFlags := append([]*Flag{}, r.persistentFlags()...)
	allFlags = append(allFlags, rootLocalFlags()...)

	w.WriteString("Flags:\n")
	w.WriteString(formatFlags(allFlags))
	w.WriteString("\n")
	w.WriteString("Use \"dep-tree [command] --help\" for more information about a command.\n")
}

// renderSubHelp renders a subcommand's help (including global flags in alphabetical order).
func renderSubHelp(w *strings.Builder, cmd *Command) {
	w.WriteString(cmd.LongDesc)
	w.WriteString("\n")
	w.WriteString("\n")
	w.WriteString("Usage:\n")
	w.WriteString("  dep-tree " + cmd.Name + " [flags]\n")
	w.WriteString("\n")
	if len(cmd.Aliases) > 0 {
		w.WriteString("Aliases:\n")
		all := append([]string{cmd.Name}, cmd.Aliases...)
		w.WriteString("  " + strings.Join(all, ", ") + "\n")
		w.WriteString("\n")
	}
	// Local flags include help and cmd-specific flags, all sorted alphabetical.
	local := []*Flag{{Name: "help", Short: "h", Kind: "bool", Default: "false",
		Help: "help for " + cmd.Name}}
	local = append(local, cmd.Flags...)
	localSorted := sortFlagsByName(local)
	w.WriteString("Flags:\n")
	w.WriteString(formatFlags(localSorted))
	w.WriteString("\n")
	// Global flags = persistent flags sorted alphabetically.
	r := &Root{}
	globals := sortFlagsByName(r.persistentFlags())
	w.WriteString("Global Flags:\n")
	w.WriteString(formatFlags(globals))
}

// renderHelpCmdHelp renders help for the help subcommand.
func renderHelpCmdHelp(w *strings.Builder) {
	w.WriteString("Help provides help for any command in the application.\n")
	w.WriteString("Simply type dep-tree help [path to command] for full details.\n")
	w.WriteString("\n")
	w.WriteString("Usage:\n")
	w.WriteString("  dep-tree help [command] [flags]\n")
	w.WriteString("\n")
	w.WriteString("Flags:\n")
	help := []*Flag{{Name: "help", Short: "h", Kind: "bool", Default: "false", Help: "help for help"}}
	w.WriteString(formatFlags(help))
	w.WriteString("\n")
	r := &Root{}
	w.WriteString("Global Flags:\n")
	w.WriteString(formatFlags(sortFlagsByName(r.persistentFlags())))
}

// Parsed holds parsed args.
type Parsed struct {
	Args     []string
	Bools    map[string]bool
	Strings  map[string]string
	Arrays   map[string][]string
}

// getCommands returns all non-help subcommands.
func getCommands() []*Command {
	return []*Command{
		entropyCommand(),
		treeCommand(),
		checkCommand(),
		explainCommand(),
		configCommand(),
	}
}

func findCommand(name string) *Command {
	for _, c := range getCommands() {
		if c.Name == name {
			return c
		}
		for _, a := range c.Aliases {
			if a == name {
				return c
			}
		}
	}
	return nil
}

// helperToStderr writes an error message to stderr.
func errPrint(msg string) {
	fmt.Fprintln(os.Stderr, "Error: "+msg)
}

// stop signals (internal error types)
type helpShown struct{}
type versionShown struct{}
type flagErr struct{ msg string }

func (e *flagErr) Error() string { return e.msg }

// Run parses and dispatches the CLI. Returns exit code.
func Run(args []string) int {
	// Special case: no args => show root help on stdout
	if len(args) == 0 {
		var sb strings.Builder
		renderRootHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}

	// Determine if first non-flag token is a known subcommand.
	// Before a subcommand is found, flags like -h/--help or -v/--version
	// are consumed preemptively.
	// We try to route as follows:
	// 1. If there's a subcommand token before the first unknown token,
	//    dispatch to it.
	// 2. Otherwise treat this as the root (default) command.

	// Find first non-flag-looking arg that matches a subcommand
	cmdName := ""
	cmdIdx := -1
	for i, a := range args {
		if strings.HasPrefix(a, "-") {
			continue
		}
		if a == "help" {
			cmdName = "help"
			cmdIdx = i
			break
		}
		if findCommand(a) != nil {
			cmdName = a
			cmdIdx = i
			break
		}
		// First non-flag non-command arg => treat as root's arg
		break
	}

	if cmdName == "" {
		// Root command: parse as default (entropy-like). But actually the default
		// command when no subcommand is given takes file args and renders entropy.
		return runRoot(args)
	}

	// For help subcommand
	if cmdName == "help" {
		return runHelp(args[cmdIdx+1:])
	}

	// Subcommand dispatch:
	// The args before cmdIdx are not allowed on subcommand invocation;
	// but cobra allows them if they're persistent flags. We merge them.
	var merged []string
	merged = append(merged, args[:cmdIdx]...)
	merged = append(merged, args[cmdIdx+1:]...)
	cmd := findCommand(cmdName)
	return runCommand(cmd, merged)
}

func runHelp(args []string) int {
	// If no args: show root help
	if len(args) == 0 {
		var sb strings.Builder
		renderRootHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}
	// Check first arg - flag?
	if strings.HasPrefix(args[0], "-") {
		// Unknown flag -> error
		if args[0] == "-h" || args[0] == "--help" {
			var sb strings.Builder
			renderHelpCmdHelp(&sb)
			os.Stdout.WriteString(sb.String())
			return 0
		}
		errPrint("unknown flag: " + args[0])
		return 1
	}
	target := args[0]
	if target == "help" {
		var sb strings.Builder
		renderHelpCmdHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}
	cmd := findCommand(target)
	if cmd == nil {
		// cobra prints root help for unknown
		var sb strings.Builder
		renderRootHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}
	var sb strings.Builder
	renderSubHelp(&sb, cmd)
	os.Stdout.WriteString(sb.String())
	return 0
}

