	Arrays   map[string][]string
}

// getCommands returns all non-help subcommands.
func getCommands() []*Command {
	return []*Command{
		entropyCommand(),
		treeCommand(),
		checkCommand(),
		explainCommand(),
		configCommand(),
	}
}

func findCommand(name string) *Command {
	for _, c := range getCommands() {
		if c.Name == name {
			return c
		}
		for _, a := range c.Aliases {
			if a == name {
				return c
			}
		}
	}
	return nil
}

// helperToStderr writes an error message to stderr.
func errPrint(msg string) {
	fmt.Fprintln(os.Stderr, "Error: "+msg)
}

// stop signals (internal error types)
type helpShown struct{}
type versionShown struct{}
type flagErr struct{ msg string }

func (e *flagErr) Error() string { return e.msg }

// Run parses and dispatches the CLI. Returns exit code.
func Run(args []string) int {
	// Special case: no args => show root help on stdout
	if len(args) == 0 {
		var sb strings.Builder
		renderRootHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}

	// Determine if first non-flag token is a known subcommand.
	// Before a subcommand is found, flags like -h/--help or -v/--version
	// are consumed preemptively.
	// We try to route as follows:
	// 1. If there's a subcommand token before the first unknown token,
	//    dispatch to it.
	// 2. Otherwise treat this as the root (default) command.

	// Find first non-flag-looking arg that matches a subcommand
	cmdName := ""
	cmdIdx := -1
	for i, a := range args {
		if strings.HasPrefix(a, "-") {
			continue
		}
		if a == "help" {
			cmdName = "help"
			cmdIdx = i
			break
		}
		if findCommand(a) != nil {
			cmdName = a
			cmdIdx = i
			break
		}
		// First non-flag non-command arg => treat as root's arg
		break
	}

	if cmdName == "" {
		// Root command: parse as default (entropy-like). But actually the default
		// command when no subcommand is given takes file args and renders entropy.
		return runRoot(args)
	}

	// For help subcommand
	if cmdName == "help" {
		return runHelp(args[cmdIdx+1:])
	}

	// Subcommand dispatch:
	// The args before cmdIdx are not allowed on subcommand invocation;
	// but cobra allows them if they're persistent flags. We merge them.
	var merged []string
	merged = append(merged, args[:cmdIdx]...)
	merged = append(merged, args[cmdIdx+1:]...)
	cmd := findCommand(cmdName)
	return runCommand(cmd, merged)
}

func runHelp(args []string) int {
	// If no args: show root help
	if len(args) == 0 {
		var sb strings.Builder
		renderRootHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}
	// Check first arg - flag?
	if strings.HasPrefix(args[0], "-") {
		// Unknown flag -> error
		if args[0] == "-h" || args[0] == "--help" {
			var sb strings.Builder
			renderHelpCmdHelp(&sb)
			os.Stdout.WriteString(sb.String())
			return 0
		}
		errPrint("unknown flag: " + args[0])
		return 1
	}
	target := args[0]
	if target == "help" {
		var sb strings.Builder
		renderHelpCmdHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}
	cmd := findCommand(target)
	if cmd == nil {
		// cobra prints root help for unknown
		var sb strings.Builder
		renderRootHelp(&sb)
		os.Stdout.WriteString(sb.String())
		return 0
	}
	var sb strings.Builder
	renderSubHelp(&sb, cmd)
	os.Stdout.WriteString(sb.String())
	return 0
}

