package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Build runCommand, runRoot, and individual command definitions.

func runCommand(cmd *Command, args []string) int {
	// combine persistent flags + local flags
	r := &Root{}
	all := append([]*Flag{}, r.persistentFlags()...)
	all = append(all, cmd.Flags...)
	all = append(all, &Flag{Name: "help", Short: "h", Kind: "bool", Default: "false", Help: "help for " + cmd.Name})
	parsed, err := parseArgs(args, all, true, cmd.Name)
	if err != nil {
		errPrint(err.Error())
		return 1
	}
	if parsed.Bools["help"] {
		var sb strings.Builder
		renderSubHelp(&sb, cmd)
		os.Stdout.WriteString(sb.String())
		return 0
	}
	// Validate args count
	if cmd.ArgsExact >= 0 {
		if len(parsed.Args) != cmd.ArgsExact {
			errPrint(fmt.Sprintf("accepts %d arg(s), received %d", cmd.ArgsExact, len(parsed.Args)))
			return 1
		}
	} else if cmd.ArgsMin >= 0 && len(parsed.Args) < cmd.ArgsMin {
		errPrint(fmt.Sprintf("requires at least %d arg(s), only received %d", cmd.ArgsMin, len(parsed.Args)))
		return 1
	}

	// Populate root
	r = fromParsed(parsed)
	return cmd.Run(r, parsed)
}

func fromParsed(parsed *Parsed) *Root {
	r := &Root{
		Config:                          parsed.Strings["config"],
		UnwrapExports:                   parsed.Bools["unwrap-exports"],
		JsTsConfigPaths:                 parsed.Bools["js-tsconfig-paths"],
		JsWorkspaces:                    parsed.Bools["js-workspaces"],
		PythonExcludeConditionalImports: parsed.Bools["python-exclude-conditional-imports"],
		Only:                            parsed.Arrays["only"],
		Exclude:                         parsed.Arrays["exclude"],
	}
	if r.Config == "" {
		r.Config = ".dep-tree.yml"
	}
	return r
}

// runRoot is the default command: behaves like entropy.
// Also handles -h/--help -> root help and -v/--version -> version.
func runRoot(args []string) int {
	r := &Root{}
	all := append([]*Flag{}, r.persistentFlags()...)
