func globHasMatch(pattern string) bool {
	// Very simple: use filepath.Glob for simple patterns.
	// For '**' we accept and defer to filepath.Walk-like logic.
	// Fallback: direct file check
	if pathExists(pattern) {
		return true
	}
	matches, err := filepath.Glob(pattern)
	if err == nil && len(matches) > 0 {
		return true
	}
	// If pattern has **, approximate by walking
	if strings.Contains(pattern, "**") {
		// walk cwd, check each file path
		found := false
		rootDir := "."
		// find highest directory without wildcards
		seg := strings.Split(pattern, "/")
		up := ""
		for _, s := range seg {
			if strings.ContainsAny(s, "*?[") {
				break
			}
			if up == "" {
				up = s
			} else {
				up += "/" + s
			}
		}
		if up != "" {
			if pathExists(up) {
				rootDir = up
			} else {
				return false
			}
		}
		// Use filepath.WalkDir
		_ = filepath.Walk(rootDir, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}
			if info.IsDir() {
				return nil
			}
			// Normalize
			p := filepath.ToSlash(path)
			if matchDoubleGlob(pattern, p) {
				found = true
			}
			return nil
		})
		return found
	}
	return false
}

