func globMatch(pat, name []string) bool {
	if len(pat) == 0 {
		return len(name) == 0
	}
	if pat[0] == "**" {
		if len(pat) == 1 {
			return true
		}
		for i := 0; i <= len(name); i++ {
			if globMatch(pat[1:], name[i:]) {
				return true
			}
		}
		return false
	}
	if len(name) == 0 {
		return false
	}
	if !segMatch(pat[0], name[0]) {
		return false
	}
	return globMatch(pat[1:], name[1:])
}

func segMatch(pat, s string) bool {
	ok, _ := filepath.Match(pat, s)
	return ok
}

