package cli

import (
	_ "embed"
	"fmt"
	"os"
	"sort"
	"strings"
)

//go:embed sample_config.yml
var sampleConfig []byte

const version = "v0.23.4"

const banner = `
      ____         _ __       _
     |  _ \   ___ |  _ \    _| |_  _ __  ___   ___
     | | | | / _ \| |_) |  |_   _||  __|/ _ \ / _ \
     | |_| ||  __/| .__/     | |  | |  |  __/|  __/
     |____/  \__| |_|        | \__|_|   \___| \___|
`

// Flag represents a single flag.
type Flag struct {
	Name       string
	Short      string
	Kind       string // "bool", "string", "stringArray"
	Help       string
	Default    string
	Persistent bool
}

// repr returns the left-hand column text for a flag.
func (f *Flag) repr() string {
	var sb strings.Builder
	sb.WriteString("  ")
	if f.Short != "" {
		sb.WriteString("-" + f.Short + ", ")
	} else {
		sb.WriteString("    ")
	}
	sb.WriteString("--" + f.Name)
	switch f.Kind {
	case "string":
		sb.WriteString(" string")
	case "stringArray":
		sb.WriteString(" stringArray")
	}
	return sb.String()
}

func (f *Flag) description() string {
	d := f.Help
	if f.Kind == "string" && f.Default != "" {
		d += fmt.Sprintf(" (default %s)", f.Default)
	}
	return d
}

// Command represents a subcommand.
type Command struct {
	Name      string
	Aliases   []string
	LongDesc  string
	ArgsExact int // -1 for no exact check
	ArgsMin   int // -1 for no minimum
	Flags     []*Flag
	Run       func(r *Root, p *Parsed) int
}

// Root holds global flag state.
type Root struct {
	Config                          string
	UnwrapExports                   bool
