// Run parses and dispatches the CLI. Returns exit code.
func Run(args []string) int {
	if len(args) == 0 {
		fmt.Print(renderRootHelp())
		return 0
	}

	// Check for pre-parse special: -v/--version bare short chain must be pre-checked
	// (because pflag in the original binary rejects -vX... chains where v is first).
	for _, a := range args {
		if strings.HasPrefix(a, "--") {
			continue
		}
		if len(a) > 2 && strings.HasPrefix(a, "-v") {
			errPrint("unknown shorthand flag: 'v' in " + a)
			return 1
		}
	}

	// Identify command routing:
	// Walk through args treating known flags (with their value consumption)
	// and looking for the first positional arg that is a subcommand.
	cmdName, cmdIdx, preErr := findSubcommand(args)
	if preErr != nil {
		errPrint(preErr.Error())
		return 1
	}

	// Check for root-level help/version special handling BEFORE dispatch.
	hasHelp := false
	for _, a := range args {
		if a == "-h" || a == "--help" {
			hasHelp = true
			break
		}
	}

	// Version: args[0] is -v or --version, no help
	if !hasHelp && (args[0] == "-v" || args[0] == "--version") {
		fmt.Println("dep-tree version " + version)
		return 0
	}

	if cmdName == "" {
		// Root command (default)
		return runRoot(args, hasHelp)
	}
	if cmdName == "help" {
		return runHelp(args[cmdIdx+1:])
	}

	// Route to subcommand: merge args before and after cmdIdx.
	merged := append([]string{}, args[:cmdIdx]...)
	merged = append(merged, args[cmdIdx+1:]...)
	cmd := findCommand(cmdName)
	return runCommand(cmd, merged)
}

// findSubcommand walks args and returns the (subcommand, index, error).
// Flags with values are properly consumed.
func findSubcommand(args []string) (string, int, error) {
	allFlags := append([]*Flag{}, persistentFlags()...)
	allFlags = append(allFlags, rootLocalFlags()...)
	byLong := map[string]*Flag{}
	byShort := map[string]*Flag{}
	for _, f := range allFlags {
		byLong[f.Name] = f
		if f.Short != "" {
			byShort[f.Short] = f
		}
	}

	i := 0
	for i < len(args) {
		a := args[i]
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			eq := strings.Index(name, "=")
			hasVal := eq >= 0
			if hasVal {
				name = name[:eq]
			}
			f, ok := byLong[name]
			if !ok {
				// Unknown long flag - we can't advance; treat as opaque flag consumed alone.
				i++
				continue
			}
			if f.Kind == "bool" || hasVal {
				i++
				continue
			}
			// needs value
			i += 2
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short chain
			body := a[1:]
			j := 0
			consumedNext := false
			for j < len(body) {
				ch := string(body[j])
				f, ok := byShort[ch]
				if !ok {
					// unknown short - skip whole arg
					j = len(body)
					break
				}
				if f.Kind == "bool" {
					j++
					continue
				}
				// string/stringArray: rest of body or next argv
				if j+1 < len(body) {
					// value is rest
					j = len(body)
				} else {
					consumedNext = true
					j = len(body)
				}
			}
			if consumedNext {
				i += 2
			} else {
				i++
			}
			continue
		}
		// positional
		if a == "help" {
			return "help", i, nil
		}
		if findCommand(a) != nil {
			return a, i, nil
		}
		return "", -1, nil // no subcommand
	}
	return "", -1, nil
}

