func runRoot(args []string, hasHelp bool) int {
	allFlags := append([]*Flag{}, persistentFlags()...)
	allFlags = append(allFlags, rootLocalFlags()...)
	parsed, err := parseArgs(args, allFlags)
	if err != nil {
		errPrint(err.Error())
		return 1
	}
	if parsed.Bools["help"] {
		fmt.Print(renderRootHelp())
		return 0
	}
	if parsed.Bools["version"] {
		fmt.Println("dep-tree version " + version)
		return 0
	}
	// No help/version set. This is default command (entropy): needs >=1 arg.
	if len(parsed.Args) < 1 {
		errPrint("requires at least 1 arg(s), only received 0")
		return 1
	}
	for _, a := range parsed.Args {
		if !pathExists(a) {
			errPrint(a + " does not match with any existing file")
			return 1
		}
	}
	// Fallback: we don't implement entropy rendering.
	errPrint("entropy rendering not supported")
	return 1
}

// runHelp handles "help [cmd]" subcommand.
func runHelp(args []string) int {
	if len(args) == 0 {
		fmt.Print(renderRootHelp())
		return 0
	}
	a := args[0]
	if strings.HasPrefix(a, "-") {
		if a == "-h" || a == "--help" {
			fmt.Print(renderHelpHelp())
			return 0
		}
		errPrint("unknown flag: " + a)
		return 1
	}
	if a == "help" {
		fmt.Print(renderHelpHelp())
		return 0
	}
	cmd := findCommand(a)
	if cmd == nil {
		fmt.Print(renderRootHelp())
		return 0
	}
	fmt.Print(renderSubHelp(cmd))
	return 0
}

// runCommand runs a non-help subcommand with the given (already-merged) args.
func runCommand(cmd *Command, args []string) int {
	allFlags := append([]*Flag{}, persistentFlags()...)
	allFlags = append(allFlags, cmd.Flags...)
	allFlags = append(allFlags, &Flag{
		Name: "help", Short: "h", Kind: "bool", Default: "false",
		Help: "help for " + cmd.Name,
	})
	parsed, err := parseArgs(args, allFlags)
	if err != nil {
		errPrint(err.Error())
		return 1
	}
	if parsed.Bools["help"] {
		fmt.Print(renderSubHelp(cmd))
		return 0
	}
	// args count validation
	if cmd.ArgsExact >= 0 {
		if len(parsed.Args) != cmd.ArgsExact {
			errPrint(fmt.Sprintf("accepts %d arg(s), received %d", cmd.ArgsExact, len(parsed.Args)))
			return 1
		}
	} else if cmd.ArgsMin >= 0 {
		if len(parsed.Args) < cmd.ArgsMin {
			errPrint(fmt.Sprintf("requires at least %d arg(s), only received %d", cmd.ArgsMin, len(parsed.Args)))
			return 1
		}
	}
	r := fromParsed(parsed)
	return cmd.Run(r, parsed)
}

func fromParsed(parsed *Parsed) *Root {
	r := &Root{
		Config:                          parsed.Strings["config"],
		UnwrapExports:                   parsed.Bools["unwrap-exports"],
		JsTsConfigPaths:                 parsed.Bools["js-tsconfig-paths"],
		JsWorkspaces:                    parsed.Bools["js-workspaces"],
		PythonExcludeConditionalImports: parsed.Bools["python-exclude-conditional-imports"],
		Only:                            parsed.Arrays["only"],
		Exclude:                         parsed.Arrays["exclude"],
	}
	if r.Config == "" {
		r.Config = ".dep-tree.yml"
	}
	return r
}

func pathExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}
