	JsWorkspaces                    bool
	PythonExcludeConditionalImports bool
	Only                            []string
	Exclude                         []string
}

// persistentFlags returns the persistent flags in registration order.
func persistentFlags() []*Flag {
	return []*Flag{
		{Name: "config", Short: "c", Kind: "string", Default: ".dep-tree.yml",
			Help: "path to dep-tree's config file.", Persistent: true},
		{Name: "unwrap-exports", Kind: "bool", Default: "false",
			Help: "trace re-exported symbols to the file where they are declared. (default false)", Persistent: true},
		{Name: "js-tsconfig-paths", Kind: "bool", Default: "true",
			Help: "follow the tsconfig.json paths while resolving imports. (default true)", Persistent: true},
		{Name: "js-workspaces", Kind: "bool", Default: "true",
			Help: "take the workspaces attribute in the root package.json into account for resolving paths. (default true)", Persistent: true},
		{Name: "python-exclude-conditional-imports", Kind: "bool", Default: "false",
			Help: "exclude imports wrapped inside if or try statements. (default false)", Persistent: true},
		{Name: "only", Kind: "stringArray", Default: "",
			Help: "Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.", Persistent: true},
		{Name: "exclude", Kind: "stringArray", Default: "",
			Help: "Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.", Persistent: true},
	}
}

// rootLocalFlags returns local (non-persistent) flags at root.
func rootLocalFlags() []*Flag {
	return []*Flag{
		{Name: "help", Short: "h", Kind: "bool", Default: "false", Help: "help for dep-tree"},
		{Name: "version", Short: "v", Kind: "bool", Default: "false", Help: "version for dep-tree"},
	}
}

func formatFlags(flags []*Flag) string {
	maxLen := 0
	reprs := make([]string, len(flags))
	for i, f := range flags {
		reprs[i] = f.repr()
		if len(reprs[i]) > maxLen {
			maxLen = len(reprs[i])
		}
	}
	var sb strings.Builder
	for i, f := range flags {
		sb.WriteString(reprs[i])
		sb.WriteString(strings.Repeat(" ", maxLen-len(reprs[i])+3))
		sb.WriteString(f.description())
		sb.WriteString("\n")
	}
	return sb.String()
}

func sortFlagsByName(flags []*Flag) []*Flag {
	out := make([]*Flag, len(flags))
	copy(out, flags)
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].Name < out[j].Name
	})
	return out
}

func renderRootHelp() string {
	var sb strings.Builder
	sb.WriteString(banner)
	sb.WriteString("\n")
	sb.WriteString("Usage:\n")
	sb.WriteString("  dep-tree [command]\n")
	sb.WriteString("\n")
	sb.WriteString("Examples:\n")
	sb.WriteString("$ dep-tree src/index.ts\n")
	sb.WriteString("$ dep-tree entropy src/index.ts\n")
	sb.WriteString("$ dep-tree tree package/main.py --unwrap-exports\n")
	sb.WriteString("$ dep-tree check\n")
	sb.WriteString("\n")
	sb.WriteString("Visualize your dependencies graphically\n")
	sb.WriteString("  entropy     (default) Renders a 3d force-directed graph in the browser\n")
	sb.WriteString("  tree        Render the dependency tree starting from the provided entrypoint\n")
	sb.WriteString("\n")
	sb.WriteString("Check your dependencies against your own rules\n")
	sb.WriteString("  check       Checks that the dependency rules defined in the configuration file are not broken\n")
	sb.WriteString("\n")
	sb.WriteString("Display what are the dependencies between two portions of code\n")
	sb.WriteString("  explain     Shows all the dependencies between two parts of the code\n")
	sb.WriteString("\n")
	sb.WriteString("Additional Commands:\n")
	sb.WriteString("  config      Generates a sample config in case that there's not already one present\n")
	sb.WriteString("  help        Help about any command\n")
