func renderSubHelp(cmd *Command) string {
	var sb strings.Builder
	sb.WriteString(cmd.LongDesc)
	sb.WriteString("\n\n")
	sb.WriteString("Usage:\n")
	sb.WriteString("  dep-tree " + cmd.Name + " [flags]\n")
	sb.WriteString("\n")
	if len(cmd.Aliases) > 0 {
		all := append([]string{cmd.Name}, cmd.Aliases...)
		sb.WriteString("Aliases:\n")
		sb.WriteString("  " + strings.Join(all, ", ") + "\n")
		sb.WriteString("\n")
	}
	local := []*Flag{{Name: "help", Short: "h", Kind: "bool", Default: "false", Help: "help for " + cmd.Name}}
	local = append(local, cmd.Flags...)
	local = sortFlagsByName(local)
	sb.WriteString("Flags:\n")
	sb.WriteString(formatFlags(local))
	sb.WriteString("\n")
	sb.WriteString("Global Flags:\n")
	sb.WriteString(formatFlags(sortFlagsByName(persistentFlags())))
	return sb.String()
}

func renderHelpHelp() string {
	var sb strings.Builder
	sb.WriteString("Help provides help for any command in the application.\n")
	sb.WriteString("Simply type dep-tree help [path to command] for full details.\n\n")
	sb.WriteString("Usage:\n")
	sb.WriteString("  dep-tree help [command] [flags]\n\n")
	sb.WriteString("Flags:\n")
	help := []*Flag{{Name: "help", Short: "h", Kind: "bool", Default: "false", Help: "help for help"}}
	sb.WriteString(formatFlags(help))
	sb.WriteString("\n")
