	sb.WriteString(formatFlags(sortFlagsByName(persistentFlags())))
	return sb.String()
}

func errPrint(msg string) {
	fmt.Fprintln(os.Stderr, "Error: "+msg)
}

// Parsed holds parsed values
type Parsed struct {
	Args    []string
	Bools   map[string]bool
	Strings map[string]string
	Arrays  map[string][]string
}

type flagErr struct{ msg string }

func (e *flagErr) Error() string { return e.msg }

func getCommands() []*Command {
	return []*Command{
		entropyCommand(),
		treeCommand(),
		checkCommand(),
		explainCommand(),
		configCommand(),
	}
}

func findCommand(name string) *Command {
	for _, c := range getCommands() {
		if c.Name == name {
			return c
		}
		for _, a := range c.Aliases {
			if a == name {
				return c
			}
		}
	}
	return nil
}

// Run parses and dispatches the CLI. Returns exit code.
func Run(args []string) int {
	if len(args) == 0 {
		fmt.Print(renderRootHelp())
		return 0
	}

	// Check for pre-parse special: -v/--version bare short chain must be pre-checked
	// (because pflag in the original binary rejects -vX... chains where v is first).
	for _, a := range args {
		if strings.HasPrefix(a, "--") {
			continue
		}
		if len(a) > 2 && strings.HasPrefix(a, "-v") {
			errPrint("unknown shorthand flag: 'v' in " + a)
			return 1
		}
	}

	// Identify command routing:
	// Walk through args treating known flags (with their value consumption)
	// and looking for the first positional arg that is a subcommand.
	cmdName, cmdIdx, preErr := findSubcommand(args)
	if preErr != nil {
		errPrint(preErr.Error())
		return 1
	}

	// Check for root-level help/version special handling BEFORE dispatch.
	hasHelp := false
	for _, a := range args {
		if a == "-h" || a == "--help" {
			hasHelp = true
			break
		}
	}

	// Version: args[0] is -v or --version, no help
	if !hasHelp && (args[0] == "-v" || args[0] == "--version") {
		fmt.Println("dep-tree version " + version)
		return 0
	}

	if cmdName == "" {
		// Root command (default)
		return runRoot(args, hasHelp)
	}
	if cmdName == "help" {
		return runHelp(args[cmdIdx+1:])
	}

	// Route to subcommand: merge args before and after cmdIdx.
	merged := append([]string{}, args[:cmdIdx]...)
	merged = append(merged, args[cmdIdx+1:]...)
	cmd := findCommand(cmdName)
	return runCommand(cmd, merged)
}

// findSubcommand walks args and returns the (subcommand, index, error).
// Flags with values are properly consumed.
func findSubcommand(args []string) (string, int, error) {
	allFlags := append([]*Flag{}, persistentFlags()...)
	allFlags = append(allFlags, rootLocalFlags()...)
	byLong := map[string]*Flag{}
	byShort := map[string]*Flag{}
	for _, f := range allFlags {
		byLong[f.Name] = f
		if f.Short != "" {
			byShort[f.Short] = f
		}
	}

	i := 0
	for i < len(args) {
		a := args[i]
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			eq := strings.Index(name, "=")
			hasVal := eq >= 0
			if hasVal {
				name = name[:eq]
			}
			f, ok := byLong[name]
			if !ok {
				// Unknown long flag - we can't advance; treat as opaque flag consumed alone.
				i++
				continue
			}
			if f.Kind == "bool" || hasVal {
				i++
				continue
			}
			// needs value
			i += 2
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short chain
			body := a[1:]
			j := 0
			consumedNext := false
			for j < len(body) {
				ch := string(body[j])
				f, ok := byShort[ch]
				if !ok {
					// unknown short - skip whole arg
					j = len(body)
					break
				}
				if f.Kind == "bool" {
					j++
					continue
				}
				// string/stringArray: rest of body or next argv
				if j+1 < len(body) {
					// value is rest
					j = len(body)
				} else {
					consumedNext = true
					j = len(body)
				}
			}
			if consumedNext {
				i += 2
			} else {
				i++
			}
			continue
		}
		// positional
		if a == "help" {
			return "help", i, nil
		}
		if findCommand(a) != nil {
			return a, i, nil
		}
		return "", -1, nil // no subcommand
	}
	return "", -1, nil
}

// runRoot handles root (default) command logic.
func runRoot(args []string, hasHelp bool) int {
	allFlags := append([]*Flag{}, persistentFlags()...)
	allFlags = append(allFlags, rootLocalFlags()...)
	parsed, err := parseArgs(args, allFlags)
	if err != nil {
		errPrint(err.Error())
		return 1
	}
	if parsed.Bools["help"] {
		fmt.Print(renderRootHelp())
		return 0
	}
	if parsed.Bools["version"] {
		fmt.Println("dep-tree version " + version)
		return 0
	}
	// No help/version set. This is default command (entropy): needs >=1 arg.
	if len(parsed.Args) < 1 {
		errPrint("requires at least 1 arg(s), only received 0")
		return 1
	}
	for _, a := range parsed.Args {
		if !pathExists(a) {
			errPrint(a + " does not match with any existing file")
			return 1
		}
	}
	// Fallback: we don't implement entropy rendering.
	errPrint("entropy rendering not supported")
	return 1
}

// runHelp handles "help [cmd]" subcommand.
func runHelp(args []string) int {
	if len(args) == 0 {
		fmt.Print(renderRootHelp())
		return 0
	}
	a := args[0]
	if strings.HasPrefix(a, "-") {
		if a == "-h" || a == "--help" {
			fmt.Print(renderHelpHelp())
			return 0
		}
		errPrint("unknown flag: " + a)
		return 1
	}
	if a == "help" {
		fmt.Print(renderHelpHelp())
		return 0
	}
	cmd := findCommand(a)
	if cmd == nil {
		fmt.Print(renderRootHelp())
		return 0
	}
	fmt.Print(renderSubHelp(cmd))
	return 0
}

// runCommand runs a non-help subcommand with the given (already-merged) args.
func runCommand(cmd *Command, args []string) int {
	allFlags := append([]*Flag{}, persistentFlags()...)
	allFlags = append(allFlags, cmd.Flags...)
	allFlags = append(allFlags, &Flag{
		Name: "help", Short: "h", Kind: "bool", Default: "false",
		Help: "help for " + cmd.Name,
	})
	parsed, err := parseArgs(args, allFlags)
	if err != nil {
		errPrint(err.Error())
		return 1
	}
	if parsed.Bools["help"] {
		fmt.Print(renderSubHelp(cmd))
		return 0
	}
	// args count validation
	if cmd.ArgsExact >= 0 {
		if len(parsed.Args) != cmd.ArgsExact {
			errPrint(fmt.Sprintf("accepts %d arg(s), received %d", cmd.ArgsExact, len(parsed.Args)))
			return 1
		}
	} else if cmd.ArgsMin >= 0 {
		if len(parsed.Args) < cmd.ArgsMin {
			errPrint(fmt.Sprintf("requires at least %d arg(s), only received %d", cmd.ArgsMin, len(parsed.Args)))
			return 1
		}
	}
	r := fromParsed(parsed)
	return cmd.Run(r, parsed)
}

func fromParsed(parsed *Parsed) *Root {
	r := &Root{
		Config:                          parsed.Strings["config"],
		UnwrapExports:                   parsed.Bools["unwrap-exports"],
		JsTsConfigPaths:                 parsed.Bools["js-tsconfig-paths"],
		JsWorkspaces:                    parsed.Bools["js-workspaces"],
		PythonExcludeConditionalImports: parsed.Bools["python-exclude-conditional-imports"],
		Only:                            parsed.Arrays["only"],
		Exclude:                         parsed.Arrays["exclude"],
	}
	if r.Config == "" {
		r.Config = ".dep-tree.yml"
	}
	return r
}

func pathExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}
