					return 1
				}
			}
			errPrint("entropy rendering not supported")
			return 1
		},
	}
}

func treeCommand() *Command {
	return &Command{
		Name:     "tree",
		LongDesc: "Render the dependency tree starting from the provided entrypoint",
		ArgsMin:  1, ArgsExact: -1,
		Flags: []*Flag{
			{Name: "json", Kind: "bool", Default: "false", Help: "render the dependency tree in a machine readable json format"},
		},
		Run: func(r *Root, p *Parsed) int {
			for _, a := range p.Args {
				if !pathExists(a) {
					errPrint(a + " does not match with any existing file")
					return 1
				}
			}
			errPrint("tree rendering not supported")
			return 1
		},
	}
}

