		Run: func(r *Root, p *Parsed) int {
			if !pathExists(r.Config) {
				if r.Config == ".dep-tree.yml" {
					errPrint("when using the `check` subcommand, a .dep-tree.yml file must be provided, you can create one sample .dep-tree.yml file executing `dep-tree config` in your terminal")
				} else {
					errPrint("open " + r.Config + ": no such file or directory")
				}
				return 1
			}
			errPrint("check rendering not supported")
			return 1
		},
	}
}

