			}
			if err := os.WriteFile(target, sampleConfig, 0600); err != nil {
				errPrint(err.Error())
				return 1
			}
			return 0
		},
	}
}

// globHasMatch checks whether the given glob pattern matches any file.
func globHasMatch(pattern string) bool {
	if pathExists(pattern) {
		return true
	}
	matches, err := filepath.Glob(pattern)
	if err == nil && len(matches) > 0 {
		return true
	}
	if strings.Contains(pattern, "**") {
		rootDir := "."
		seg := strings.Split(pattern, "/")
		up := ""
		for _, s := range seg {
			if strings.ContainsAny(s, "*?[") {
				break
			}
			if up == "" {
				up = s
			} else {
				up += "/" + s
			}
		}
		if up != "" {
			if !pathExists(up) {
				return false
			}
			rootDir = up
		}
		found := false
		_ = filepath.Walk(rootDir, func(path string, info os.FileInfo, err error) error {
			if err != nil || info == nil || info.IsDir() {
				return nil
			}
			p := filepath.ToSlash(path)
			if globMatchFull(pattern, p) {
				found = true
			}
			return nil
		})
		return found
	}
	return false
}

func globMatchFull(pattern, path string) bool {
	return globMatch(strings.Split(pattern, "/"), strings.Split(path, "/"))
}

func globMatch(pat, name []string) bool {
	if len(pat) == 0 {
		return len(name) == 0
	}
	if pat[0] == "**" {
		if len(pat) == 1 {
			return true
		}
		for i := 0; i <= len(name); i++ {
			if globMatch(pat[1:], name[i:]) {
				return true
			}
		}
		return false
	}
	if len(name) == 0 {
		return false
	}
	ok, _ := filepath.Match(pat[0], name[0])
	if !ok {
		return false
	}
	return globMatch(pat[1:], name[1:])
}
